const listOrders = `-- name: ListOrders :many
SELECT 
    o.id, o.uuid, o.order_number, o.user_id, o.status, o.subtotal, o.tax_total, o.shipping_total, o.discount_total, o.grand_total, o.currency, o.payment_status, o.payment_provider, o.payment_reference, o.shipping_address, o.billing_address, o.shipping_carrier, o.tracking_number, o.tracking_url, o.customer_note, o.admin_note, o.paid_at, o.shipped_at, o.delivered_at, o.cancelled_at, o.created_at, o.updated_at, o.deleted_at, o.order_type, o.fulfillment_status, o.metadata, o.account_id,
    u.email as customer_email,
    u.name as customer_name,
    u.surname as customer_surname,
    ca.name as company_name,
    a.uuid as account_uuid,
    a.name as account_name,
    a.type as account_type,
    (SELECT COUNT(*)::int FROM order_items oi WHERE oi.order_id = o.id) as items_count
FROM orders o
JOIN users u ON u.id = o.user_id
JOIN accounts a ON a.id = o.account_id
LEFT JOIN accounts ca ON ca.id = o.account_id AND ca.type = 'company'
WHERE o.deleted_at IS NULL
  AND (
    $1::text IS NULL
    OR o.order_number ILIKE '%' || $1 || '%'
    OR u.email ILIKE '%' || $1 || '%'
    OR u.name ILIKE '%' || $1 || '%'
    OR u.surname ILIKE '%' || $1 || '%'
    OR o.tracking_number ILIKE '%' || $1 || '%'
  )
  AND (
    $2::bigint IS NULL
    OR o.account_id = $2::bigint
  )
  AND (
    $3::text IS NULL
    OR o.status = $3::text
  )
  AND (
    $4::text IS NULL
    OR o.payment_status = $4::text
  )
  AND (
    $5::text IS NULL
    OR o.fulfillment_status = $5::text
  )
  AND (
    $6::text IS NULL
    OR o.order_type = $6::text
  )
ORDER BY o.created_at DESC
LIMIT $8 OFFSET $7
`

